import { useRef } from "react";
import { useEffect } from "react";
import { AiFillAliwangwang } from "react-icons/ai";
import axios from "axios";
const ChatBot = () => {
    const location = useLocation();
    const { age, occupation, tobacco, coverage, prompt } = location.state || {};
    const [messages, setMessages] = useState([]);
    const [input, setInput] = useState("");
    const [response, setResponse] = useState("");
    // components/MessageList.tsx

    const ref = useRef();
    useEffect(() => {
        if (messages.length) {
            ref.current?.scrollIntoView({
                behavior: "smooth",
                block: "end",
            });
        }
    }, [messages.length]);





    const handleSend = async () => {
        if (input.trim()) {
            setMessages([...messages, { text: input, user: true }]);

            const formData = {
                age,
                coverage_amt: coverage,
                tobacco,
                occupation,
                prompt: input,
                message: messages
            };
            setInput("");
            const res = await axios.post("http://localhost:5000/res", formData, {
                headers: {
                    "Content-Type": "application/json",
                },
            });


            console.log(messages)
            console.log(`response ${res.data.response}`)

            setResponse(res.data.response);
            console.log(response)
            console.log(`object ${res}`);
            // Simulate bot response
            setTimeout(() => {
                setMessages((prevMessages) => [
                    ...prevMessages,
                    { text: `Bot Answer:${res.data.response}`, user: false },
                ]);
            }, 500);
        }
    };
    return (
        <ChatContainer>
            <ChatWrapper>
                <Title>Chat with our Bot</Title>
                <MessageContainer>

                    {messages.map((msg, index) => (

                        <Message key={index} user={msg.user}>

                            <p>{msg.text}</p>
                        </Message>

                    ))}
                    <div ref={ref} />
                </MessageContainer>
                <InputContainer>
                    <ChatInput
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder="Type a message..."
                    />
                    <ChatButton onClick={handleSend}>
                        <FaPaperPlane size={18} />
                    </ChatButton>
                </InputContainer>
            </ChatWrapper>
        </ChatContainer>
    );
};

export default ChatBot;
